"""Postfix to Prefix — stack of partial expressions, operator first.

Time: O(n)   Space: O(n)
"""


class Solution:
    def postfixToPrefix(self, s: str) -> str:
        stack = []
        for ch in s:
            if ch.isalnum():
                stack.append(ch)
            else:
                right, left = stack.pop(), stack.pop()
                stack.append(ch + left + right)
        return stack[-1]
